select id, event_type, min(duration_sec) over (partition by session_id) as session_id_min_duration_sec, row_number() over (partition by event_type, page order by duration_sec, id) as seq_no, last_value(duration_sec) ignore nulls over (partition by session_id, event_type order by duration_sec, id rows between unbounded preceding and current row) as last_known_duration_sec, first_value(duration_sec) ignore nulls over w_recent as first_known_duration_sec, avg(duration_sec) over w_running as duration_sec_avg_5_prior from web_events where duration_sec between 130 and 295 window w_recent as (partition by event_type order by duration_sec, id rows between unbounded preceding and current row), w_running as (partition by page order by duration_sec, id rows between 5 preceding and 1 preceding)
